# Part 9: Boss Sprites (72x96)
L('// ===== BOSS SPRITES (72x96) =====')
L('function drawAncientTreeSpirit(c,f,sway,attackType){const O=1,BKD=2,BKM=3,BKLT=4,BKHL=5,LFD=6,LFM=7,LFL=8,LFHL=9,GL=10,GLH=11,GLD=12,BKLN=13,RTD=14,RTM=15,VND=16,VNM=17;const sx=sway,cx=36;c.rect(cx-10+sx,20,20,36,BKM);c.rect(cx-8+sx,20,16,33,BKLT);c.rect(cx-5+sx,20,10,28,BKHL);c.rect(cx+8+sx,22,6,32,BKD);for(let y=20;y<52;y+=4){c.line(cx-9+sx,y,cx-9+sx,y+2,BKD);c.line(cx+9+sx,y+1,cx+9+sx,y+3,BKD)}c.set(cx-6+sx,26,BKLN);c.set(cx-2+sx,32,BKLN);c.set(cx+3+sx,38,BKLN);c.set(cx-5+sx,44,BKLN);c.set(cx+1+sx,50,BKLN);c.set(cx-3+sx,54,BKLN);c.set(cx+4+sx,56,BKLN);c.rect(cx-16+sx,54,10,10,BKM);c.rect(cx+8+sx,54,10,10,BKM);c.rect(cx-14+sx,54,6,8,BKLT);c.rect(cx+10+sx,54,6,8,BKLT);c.set(cx-16+sx,63,RTD);c.set(cx+19+sx,63,RTD);c.line(cx-16+sx,62,cx-22+sx,70,RTM);c.set(cx-22+sx,71,RTD);c.line(cx+19+sx,62,cx+26+sx,70,RTM);c.set(cx+26+sx,71,RTD);c.ellipse(cx+sx,12,20,14,LFM);c.ellipse(cx-1+sx,11,17,11,LFL);c.ellipse(cx-2+sx,10,12,7,LFHL);c.ellipse(cx+4+sx,15,14,8,LFD);c.ellipse(cx-14+sx,10,6,5,LFM);c.ellipse(cx+16+sx,10,6,5,LFD);c.set(cx-17+sx,7,LFL);c.set(cx+19+sx,7,LFD);c.set(cx-14+sx,5,LFHL);c.set(cx+17+sx,5,LFM);c.set(cx-20+sx,9,LFD);c.set(cx+22+sx,10,LFD);c.line(cx-12+sx,26,cx-20+sx,18,BKM);c.set(cx-25+sx,11,LFM);c.set(cx-26+sx,10,LFL);c.line(cx+12+sx,26,cx+20+sx,18,BKM);c.set(cx+25+sx,11,LFM);c.set(cx+26+sx,12,LFD);if(attackType===1){c.line(cx-22+sx,68,cx-26+sx,78,RTM);c.set(cx-26+sx,79,RTD);c.line(cx+26+sx,68,cx+30+sx,78,RTM);c.set(cx+30+sx,79,RTD)}else if(attackType===2){c.line(cx-25+sx,11,cx-30+sx,26,VNM);c.line(cx-30+sx,26,cx-28+sx,40,VND);c.line(cx+25+sx,11,cx+30+sx,26,VNM);c.line(cx+30+sx,26,cx+28+sx,40,VND)}c.ellipse(cx+sx,34,6,6,GL);c.ellipse(cx+sx,34,3,3,GLH);c.set(cx+sx,33,GLD);c.set(cx-4+sx,26,GLH);c.set(cx-3+sx,26,GL);c.set(cx+3+sx,26,GLH);c.set(cx+4+sx,26,GL);c.rect(cx-4+sx,32,8,2,BKD);c.outline(O)}')
L('function createAncientTreeSpiritSprite(){const idle=[];const sw=[0,1.5,-1.5,0];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawAncientTreeSpirit(c,i,sw[i],0);idle.push(c.toFrame())}const a1=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawAncientTreeSpirit(c,i,0,i>=2?1:0);a1.push(c.toFrame())}const a2=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawAncientTreeSpirit(c,i,0,i>=2?2:0);a2.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawAncientTreeSpirit(c1,0,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawAncientTreeSpirit(c,0,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"ancient_tree_spirit",palette:ATP,animations:{idle:makeAnim("idle",idle,250,true),attack1:makeAnim("attack1",a1,150,false),attack2:makeAnim("attack2",a2,150,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,250,false)}}}')

L('function drawScorpionKing(c,f,at){const O=1,BD=2,BM=3,BL=4,BH=5,GD=6,GM=7,GL=8,PD=9,PM=10,PL=11,SD=12,SM=13,EY=14,SK=15,CR=16;const cx=36;c.ellipse(cx,46,16,9,BM);c.ellipse(cx-1,45,13,7,BL);c.ellipse(cx-2,44,8,4,BH);c.ellipse(cx+4,48,11,5,BD);c.ellipse(cx,36,13,7,BM);c.ellipse(cx,28,10,5,BM);c.ellipse(cx,21,8,5,BM);c.circleOutline(cx,46,14,GD);c.circleOutline(cx,36,11,GD);c.set(cx-12,46,GL);c.set(cx-13,36,GL);c.dither(cx-10,43,8,5,BM,BL);c.dither(cx+4,45,8,5,BM,BD);c.ellipse(cx,16,8,5,BM);c.ellipse(cx-1,15,6,4,BL);c.set(cx-4,14,BH);c.rect(cx-6,8,12,4,GM);c.set(cx-6,8,GL);c.set(cx-5,7,GM);c.set(cx-2,6,GL);c.set(cx,5,CR);c.set(cx+1,5,CR);c.set(cx+3,6,GL);c.set(cx+5,7,GM);c.set(cx+5,8,GL);c.set(cx-4,16,CR);c.set(cx-3,16,EY);c.set(cx+3,16,CR);c.set(cx+4,16,EY);c.ellipse(cx-14,18,6,4,PM);c.ellipse(cx-15,17,4,3,PL);c.set(cx-17,17,PD);c.circleOutline(cx-14,18,5,GD);c.set(cx-17,18,GL);c.ellipse(cx+14,18,6,4,PM);c.ellipse(cx+15,17,4,3,PL);c.set(cx+17,17,PD);c.circleOutline(cx+14,18,5,GD);c.set(cx+17,18,GL);for(let i=0;i<5;i++){const lo=Math.round(Math.sin(f+i*0.6)*1);const lx=cx-16+i*7;c.line(lx,52,lx-4,62+lo,BM);c.set(lx-4,62+lo,BD)}c.line(cx,14,cx,6,SM);c.line(cx,6,cx+5,3,SM);c.line(cx+5,3,cx+10,1,SM);c.set(cx+10,0,SK);c.set(cx+11,0,SD);if(at===1){c.line(cx+10,1,cx+16,14,SM);c.set(cx+16,14,SK)}else if(at===2){c.line(cx-14,18,cx-20,28,PM);c.set(cx-20,28,PD);c.line(cx+14,18,cx+20,28,PM);c.set(cx+20,28,PD)}c.outline(O)}')
L('function createScorpionKingSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawScorpionKing(c,i,0);idle.push(c.toFrame())}const a1=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawScorpionKing(c,i,i>=2?1:0);a1.push(c.toFrame())}const a2=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawScorpionKing(c,i,i>=2?2:0);a2.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawScorpionKing(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawScorpionKing(c,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"scorpion_king",palette:SKP,animations:{idle:makeAnim("idle",idle,250,true),attack1:makeAnim("attack1",a1,150,false),attack2:makeAnim("attack2",a2,150,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,250,false)}}}')

L('function drawIceDragon(c,f,at){const O=1,ID=2,IM=3,IL=4,IH=5,WH=6,SVD=7,SVM=8,SVL=9,GL=10,GLH=11,EY=12,CL=13,SP=14,SPH=15,WN=16,WNH=17;const cx=36;c.ellipse(cx,44,18,10,IM);c.ellipse(cx-1,43,14,8,IL);c.ellipse(cx-2,42,9,5,IH);c.ellipse(cx+4,46,13,6,ID);c.ellipse(cx,50,12,4,SVD);c.ellipse(cx-1,49,9,3,SVM);c.ellipse(cx-2,48,5,2,SVL);for(let i=0;i<7;i++){c.set(cx-14+i*4,42,IL);c.set(cx-13+i*4,43,IM)}c.dither(cx-14,44,10,5,IM,IL);c.dither(cx+4,46,10,5,IM,ID);c.ellipse(cx-16,32,7,8,IM);c.ellipse(cx-17,31,5,6,IL);c.ellipse(cx-15,34,4,4,ID);c.ellipse(cx-24,24,8,6,IM);c.ellipse(cx-25,23,6,5,IL);c.ellipse(cx-23,26,5,4,ID);c.rect(cx-34,24,6,4,IL);c.set(cx-34,24,IH);c.set(cx-35,25,WH);c.line(cx-27,18,cx-30,8,IM);c.set(cx-30,6,IH);c.set(cx-31,7,WH);c.line(cx-21,18,cx-18,8,IM);c.set(cx-18,6,ID);c.set(cx-17,7,IM);c.set(cx-27,22,GLH);c.set(cx-26,22,EY);c.set(cx-23,22,GLH);c.set(cx-22,22,EY);c.set(cx-32,25,CL);c.set(cx-33,26,SP);c.line(cx-8,34,cx-18,14,WN);c.line(cx-18,14,cx-26,10,WN);c.line(cx-26,10,cx-30,8,WN);c.line(cx-30,8,cx-32,12,WN);c.line(cx-32,12,cx-28,20,WN);c.line(cx-28,20,cx-20,30,WN);c.line(cx-20,30,cx-10,36,WN);c.line(cx+4,34,cx+18,16,WN);c.line(cx+18,16,cx+28,12,WN);c.line(cx+28,12,cx+32,18,WN);c.line(cx+32,18,cx+28,28,WN);c.line(cx+28,28,cx+18,34,WN);c.outline(O)}')
L('function createIceDragonSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawIceDragon(c,i,0);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawIceDragon(c,i,i);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawIceDragon(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],9))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawIceDragon(c,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"ice_dragon",palette:IDP,animations:{idle:makeAnim("idle",idle,250,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawVoidDevourer(c,f,at){const O=1,VD=2,VM=3,VL=4,VH=5,NG=6,NGH=7,BK=8,EY=9,GL=10,GLH=11,PT=12,PTH=13;const cx=36;c.ellipse(cx,28,10,11,VM);c.ellipse(cx-1,27,8,9,VL);c.ellipse(cx-2,26,5,6,VH);c.ellipse(cx+2,30,7+at,8,VD);c.line(cx-8,22,cx-14,14,VM);c.set(cx-14,13,VL);c.line(cx+8,22,cx+14,14,VM);c.set(cx+14,13,VL);c.line(cx-10,18,cx-14,12,VM);c.set(cx-14,11,VL);c.line(cx+10,18,cx+14,12,VM);c.set(cx+14,11,VL);c.line(cx-4,20,cx-2,30,NG);c.line(cx+4,20,cx+2,30,NG);c.set(cx-3,23,NGH);c.set(cx+3,23,NGH);c.set(cx-4,22,GLH);c.set(cx-3,22,EY);c.set(cx+3,22,GLH);c.set(cx+4,22,EY);c.set(cx-2,20,GL);c.set(cx+2,20,GL);c.set(cx,18,GLH);c.set(cx-6+f,20,PT);c.set(cx+6-f,19,PTH);c.set(cx-4,34-f,PT);c.set(cx+4,35-f,PTH);c.ellipse(cx,28,3,3,BK);c.dither(cx-6,22,5,5,VM,VD);c.dither(cx+2,24,5,5,VM,VD);if(at>=1){c.circle(24,8,3+at,6);c.circle(24,8,1+at,7)}c.outline(O)}')
L('function createVoidDevourerSprite(){const idle=[];const di=[0,1.5,-1.5,0];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawVoidDevourer(c,i,di[i]);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawVoidDevourer(c,i,i*2-2);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawVoidDevourer(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],11))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawVoidDevourer(c,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"void_devourer",palette:VDP,animations:{idle:makeAnim("idle",idle,250,true),attack:makeAnim("attack",attack,120,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

L('function drawFallenSaint(c,f,at){const O=1,BD=2,BM=3,BL=4,BH=5,AD=6,AM=7,AH=8,AL=9,BCA=10,BCB=11,BCC=12,BCC2=13,WH=14,CL=15,HALO=16,HV=17,MW=18;const cx=36,by=4+at;c.ellipse(cx,26+by,10,14,BCA);c.ellipse(cx-1,25+by,8,12,BCB);c.ellipse(cx+2,27+by,7,11,AD);c.line(cx-6,16+by,cx-7,38+by,AD);c.line(cx+6,16+by,cx+7,38+by,AD);c.set(cx-5,22+by,BCB);c.set(cx+5,25+by,AD);c.rect(cx-8,17+by,16,11,AM);c.rect(cx-7,17+by,14,3,AH);c.rect(cx-8,26+by,16,2,BD);c.rect(cx+4,18+by,5,8,BD);c.rect(cx-7,18+by,4,7,AL);c.line(cx-5,18+by,cx-5,26+by,BD);c.set(cx-4,19+by,AH);c.set(cx-3,19+by,AH);c.set(cx-4,23+by,AM);c.ellipse(cx,11+by,5,5,AM);c.ellipse(cx-1,10+by,4,4,AH);c.ellipse(cx+1,12+by,3,3,BD);c.ellipse(cx,8+by,6,4,AM);c.ellipse(cx-1,7+by,4,3,AH);c.set(cx-5,7+by,HALO);c.set(cx-4,6+by,HV);c.set(cx+4,7+by,HV);c.set(cx-2,5+by,CL);c.set(cx+2,5+by,CL);c.set(cx-2,11+by,WH);c.set(cx+2,11+by,WH);c.ellipse(cx-9,17+by,4,3,AM);c.ellipse(cx+9,17+by,4,3,AM);c.set(cx-11,16+by,AH);c.set(cx+11,16+by,AH);c.ellipse(cx-12,8+by,5,4,HALO);c.ellipse(cx-13,7+by,4,3,HV);c.ellipse(cx+12,8+by,5,4,HALO);c.ellipse(cx+13,7+by,4,3,HV);c.set(cx-14,6+by,CL);c.set(cx+14,6+by,CL);c.set(cx-13,4+by,HV);c.set(cx+13,4+by,HV);const llX=cx-4,lrX=cx+2,llO=Math.round(Math.sin(f)*2),lrO=Math.round(Math.sin(f+Math.PI)*2);c.rect(llX,30+by,4,5+llO,AM);c.rect(lrX,30+by,4,5+lrO,AM);c.set(llX,30+by,AL);c.set(lrX,30+by,AL);c.rect(llX-1,34+by+llO,5,4,BD);c.rect(lrX-1,34+by+lrO,5,4,BD);c.set(llX-1,34+by+llO,AM);c.set(lrX-1,34+by+lrO,AM);c.set(cx+10,12+by,MW);c.set(cx+11,12+by,MW);if(at>=2){c.rect(cx+12,10+by,2,8,MW);c.set(cx+12,10+by,WH)}c.outline(O)}')
L('function createFallenSaintSprite(){const idle=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,i,0);idle.push(c.toFrame())}const attack=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,i,i);attack.push(c.toFrame())}const hurt=[];{const c1=new PixelCanvas(72,96);drawFallenSaint(c1,0,0);hurt.push(c1.toFrame());hurt.push(flashFrame(hurt[0],18))}const death=[];for(let i=0;i<4;i++){const c=new PixelCanvas(72,96);drawFallenSaint(c,0,0);const sf=shiftFrame(c.toFrame(),0,i*2);const c2=new PixelCanvas(72,96);for(let y=0;y<96;y++)for(let x=0;x<72;x++)c2.px[y][x]=sf.data[y][x];death.push(c2.toFrame())}return{id:"fallen_saint",palette:FSP,animations:{idle:makeAnim("idle",idle,200,true),attack:makeAnim("attack",attack,100,false),hurt:makeAnim("hurt",hurt,100,false),death:makeAnim("death",death,200,false)}}}')

